def select_next_node(graph, unvisited_nodes):
    pre = graph.graph.get('precomputed', {})
    max_core_k = pre.get('max_core_k', 1)

    degrees = {}
    for n in unvisited_nodes:
        degrees[n] = graph.nodes[n]['degree']

    # Precompute sum of neighbors' degrees for unvisited nodes
    sum_neigh_deg = {}
    for n in unvisited_nodes:
        neighs = list(graph.neighbors(n))
        sum_deg = 0
        for nb in neighs:
            # Only consider neighbors still unvisited to focus on future disruption
            if nb in unvisited_nodes:
                sum_deg += degrees.get(nb, graph.nodes[nb]['degree'])
            else:
                sum_deg += graph.nodes[nb]['degree']
        sum_neigh_deg[n] = sum_deg

    # Extract needed attributes
    clustering = {n: graph.nodes[n]['clustering'] for n in unvisited_nodes}
    core_numbers = {n: graph.nodes[n]['core_number'] for n in unvisited_nodes}

    # Normalization helper
    def min_max_norm_dict(d):
        vals = list(d.values())
        mn, mx = min(vals), max(vals)
        if abs(mx - mn) < 1e-9:
            return {k: 0.0 for k in d}
        return {k: (v - mn) / (mx - mn) for k, v in d.items()}

    deg_norm = min_max_norm_dict(degrees)
    sum_neigh_deg_norm = min_max_norm_dict(sum_neigh_deg)
    clustering_vals = clustering
    core_norm = {}
    if max_core_k > 0:
        core_norm = {n: core_numbers[n] / max_core_k for n in unvisited_nodes}
    else:
        core_norm = {n: 0.0 for n in unvisited_nodes}

    best_score = -float('inf')
    next_node = None

    for n in unvisited_nodes:
        # Local disruption score: product of normalized degree and sum of neighbors' degrees
        local_disrupt = deg_norm[n] * sum_neigh_deg_norm[n]
        # Penalty on clustering: higher clustering means less disruptive removal
        penalty = 1 - clustering_vals[n]
        # Weight by normalized core number to emphasize structurally important nodes
        score = local_disrupt * penalty * (0.5 + 0.5 * core_norm[n])  # core weighted between 0.5 and 1

        if score > best_score:
            best_score = score
            next_node = n

    return next_node
